//! Workbench — generated by mobius_codegen.
//!
//! Wiring follows the egui_mobius book: Path A state lives in the
//! `state::*` cells, citizens' Path B events drain through actions
//! once per frame, and the registry handles lifecycle only.

mod citizens;
mod state;
mod theme;

use eframe::egui;
use egui_citizen::Registry;
use egui_dock::{DockArea, DockState, NodeIndex};

/// One dock tab per docked citizen instance.
#[derive(Clone, Copy, PartialEq, serde::Serialize, serde::Deserialize)]
pub enum Tab {
    Controls0,
    Controls1,
    Scope0,
    Scope1,
    System,
    Shell,
}

impl Tab {
    /// The instance id — registry name and citizen id.
    fn id(self) -> &'static str {
        match self {
            Tab::Controls0 => "controls0",
            Tab::Controls1 => "controls1",
            Tab::Scope0 => "scope0",
            Tab::Scope1 => "scope1",
            Tab::System => "system",
            Tab::Shell => "shell",
        }
    }
}

/// The dock layout plus named perspectives — saveable, deletable, with
/// a ★ startup default, persisted across restarts.
pub struct Workspace {
    pub dock: DockState<Tab>,
    store: PerspectiveStore,
    name_buf: String,
}

/// name → serialized `DockState` JSON, plus the startup default
/// (ForgePM's perspectives.json, verbatim shape).
#[derive(Default, serde::Serialize, serde::Deserialize)]
struct PerspectiveStore {
    perspectives: std::collections::BTreeMap<String, String>,
    default: Option<String>,
}

impl PerspectiveStore {
    fn path() -> Option<std::path::PathBuf> {
        dirs::config_dir().map(|d| d.join("workbench").join("perspectives.json"))
    }

    fn load() -> Self {
        Self::path()
            .and_then(|p| std::fs::read_to_string(p).ok())
            .and_then(|j| serde_json::from_str(&j).ok())
            .unwrap_or_default()
    }

    fn persist(&self) {
        let Some(path) = Self::path() else { return };
        if let Some(dir) = path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        if let Ok(j) = serde_json::to_string_pretty(self) {
            let _ = std::fs::write(path, j);
        }
    }
}

impl Workspace {
    fn new() -> Self {
        let store = PerspectiveStore::load();
        // The ★ default loads on startup; otherwise the @layout default.
        let dock = store
            .default
            .as_ref()
            .and_then(|n| store.perspectives.get(n))
            .and_then(|j| serde_json::from_str(j).ok())
            .unwrap_or_else(default_layout);
        Self {
            dock,
            store,
            name_buf: String::new(),
        }
    }

    /// The 🗔 Perspectives menu — ★ marks the startup default.
    ///
    /// Close-on-click-OUTSIDE, not egui's default close-on-any-click —
    /// the default kills the name text field the moment it is clicked.
    pub fn perspectives_menu(&mut self, ui: &mut egui::Ui) {
        let config = egui::containers::menu::MenuConfig::new()
            .close_behavior(egui::PopupCloseBehavior::CloseOnClickOutside);
        egui::containers::menu::MenuButton::new("🗔 Perspectives")
            .config(config)
            .ui(ui, |ui| {
                if ui.button("Reset to default").clicked() {
                    self.dock = default_layout();
                    ui.close();
                }
                if !self.store.perspectives.is_empty() {
                    ui.separator();
                }
                let mut apply = None;
                let mut delete = None;
                let mut star = None;
                for (name, json) in &self.store.perspectives {
                    ui.horizontal(|ui| {
                        let starred = self.store.default.as_deref() == Some(name.as_str());
                        if ui
                            .small_button(if starred { "★" } else { "☆" })
                            .on_hover_text("Load this perspective at startup")
                            .clicked()
                        {
                            star = Some(name.clone());
                        }
                        if ui.button(name).clicked() {
                            apply = Some(json.clone());
                        }
                        if ui.small_button("✖").clicked() {
                            delete = Some(name.clone());
                        }
                    });
                }
                if let Some(name) = star {
                    // Toggle: starring the current default clears it.
                    self.store.default =
                        if self.store.default.as_deref() == Some(name.as_str()) {
                            None
                        } else {
                            Some(name)
                        };
                    self.store.persist();
                }
                if let Some(json) = apply {
                    if let Ok(layout) = serde_json::from_str(&json) {
                        self.dock = layout;
                    }
                    ui.close();
                }
                if let Some(name) = delete {
                    self.store.perspectives.remove(&name);
                    if self.store.default.as_deref() == Some(name.as_str()) {
                        self.store.default = None;
                    }
                    self.store.persist();
                }
                ui.separator();
                ui.horizontal(|ui| {
                    ui.add(
                        egui::TextEdit::singleline(&mut self.name_buf)
                            .desired_width(120.0)
                            .hint_text("name"),
                    );
                    let ok = !self.name_buf.trim().is_empty();
                    if ui.add_enabled(ok, egui::Button::new("💾 Save current")).clicked() {
                        if let Ok(json) = serde_json::to_string(&self.dock) {
                            self.store
                                .perspectives
                                .insert(self.name_buf.trim().to_owned(), json);
                            self.store.persist();
                        }
                        self.name_buf.clear();
                    }
                });
            });
    }
}

/// The @layout default — Reset returns here.
fn default_layout() -> DockState<Tab> {

    // Dock layout from the @layout dock() directives.
    let mut dock_state = DockState::new(vec![Tab::Scope0, Tab::Scope1]);
    let _ = dock_state.main_surface_mut().split_left(NodeIndex::root(), 0.30, vec![Tab::Controls0, Tab::Controls1]);
    let [_, bottom_node] = dock_state.main_surface_mut().split_below(NodeIndex::root(), 0.65, vec![Tab::System]);
    let _ = dock_state.main_surface_mut().split_right(bottom_node, 0.5, vec![Tab::Shell]);
    dock_state
}

struct App {
    registry: Registry,
    workspace: Workspace,
    chrome: state::Chrome,
    ch0: state::Channel,
    ch1: state::Channel,
    log: state::Log,
    ribbon: citizens::Ribbon,
    controls0: citizens::Controls,
    controls1: citizens::Controls,
    scope0: citizens::Scope,
    scope1: citizens::Scope,
    system: citizens::System,
    shell: citizens::Shell,
}

impl App {
    fn new() -> Self {
        let mut registry = Registry::new();
        let ribbon_state = registry.add().with_name("ribbon");
        let controls0_state = registry.add().with_name("controls0");
        let controls1_state = registry.add().with_name("controls1");
        let scope0_state = registry.add().with_name("scope0");
        let scope1_state = registry.add().with_name("scope1");
        let system_state = registry.add().with_name("system");
        let shell_state = registry.add().with_name("shell");
        registry.activate("controls0");
        let _ = registry.drain_messages(); // discard setup messages
        let app = Self {
            registry,
            workspace: Workspace::new(),
            chrome: state::Chrome::new(),
            ch0: state::Channel::new(),
            ch1: state::Channel::new(),
            log: state::Log::new(),
            ribbon: citizens::Ribbon::with_id(ribbon_state, "ribbon"),
            controls0: citizens::Controls::with_id(controls0_state, "controls0"),
            controls1: citizens::Controls::with_id(controls1_state, "controls1"),
            scope0: citizens::Scope::with_id(scope0_state, "scope0"),
            scope1: citizens::Scope::with_id(scope1_state, "scope1"),
            system: citizens::System::with_id(system_state, "system"),
            shell: citizens::Shell::with_id(shell_state, "shell"),
        };
        startup::banner(&app.log);
        app
    }
}

struct TabViewer<'a> {
    registry: &'a mut Registry,
    ch0: &'a state::Channel,
    ch1: &'a state::Channel,
    log: &'a state::Log,
    controls0: &'a mut citizens::Controls,
    controls1: &'a mut citizens::Controls,
    scope0: &'a mut citizens::Scope,
    scope1: &'a mut citizens::Scope,
    system: &'a mut citizens::System,
    shell: &'a mut citizens::Shell,
}

impl egui_dock::TabViewer for TabViewer<'_> {
    type Tab = Tab;

    fn id(&mut self, tab: &mut Tab) -> egui::Id {
        egui::Id::new(tab.id())
    }

    fn title(&mut self, tab: &mut Tab) -> egui::WidgetText {
        tab.id().into()
    }

    fn ui(&mut self, ui: &mut egui::Ui, tab: &mut Tab) {
        match tab {
            Tab::Controls0 => self.controls0.show(ui, self.ch0),
            Tab::Controls1 => self.controls1.show(ui, self.ch1),
            Tab::Scope0 => self.scope0.show(ui, self.ch0),
            Tab::Scope1 => self.scope1.show(ui, self.ch1),
            Tab::System => self.system.show(ui, self.log),
            Tab::Shell => self.shell.show(ui),
        }
    }

    fn on_tab_button(&mut self, tab: &mut Tab, response: &egui::Response) {
        if response.clicked() {
            self.registry.activate(tab.id());
        }
    }
}

impl eframe::App for App {
    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        let ctx = ui.ctx().clone();
        self.chrome.clock.set(wall_clock());
        ctx.request_repaint_after(std::time::Duration::from_millis(250));

        egui::Panel::top("ribbon").show(ui, |ui| {
            self.ribbon.show(ui, &self.chrome, &mut self.workspace);
        });

        let mut viewer = TabViewer {
            registry: &mut self.registry,
            ch0: &self.ch0,
            ch1: &self.ch1,
            log: &self.log,
            controls0: &mut self.controls0,
            controls1: &mut self.controls1,
            scope0: &mut self.scope0,
            scope1: &mut self.scope1,
            system: &mut self.system,
            shell: &mut self.shell,
        };
        DockArea::new(&mut self.workspace.dock).show_inside(ui, &mut viewer);

        // egui_lens's System Info button sets a temp-memory flag;
        // answering it is the host's job (per egui_lens's own comment).
        let info_id = egui::Id::new("show_system_info");
        if ui.ctx().memory(|mem| mem.data.get_temp::<bool>(info_id).unwrap_or(false)) {
            startup::system_info(&self.log);
            ui.ctx().memory_mut(|mem| mem.data.remove::<bool>(info_id));
        }

        about_window(&ctx, &self.chrome);

        // Path B: drain the `actions` outbox through actions.
        for cmd in std::mem::take(&mut self.ribbon.outbox_actions) {
            actions::handle_actions(cmd, &self.chrome, &self.log);
        }
        // Registry lifecycle messages — drained after the panels show.
        for _msg in self.registry.drain_messages() {}
    }
}

/// The About window, from the `about(...)` layout directive.
fn about_window(ctx: &egui::Context, chrome: &state::Chrome) {
    if !chrome.show_about.get() {
        return;
    }
    let mut open = true;
    egui::Window::new("About Workbench")
        .collapsible(false)
        .resizable(true)
        .default_width(460.0)
        .pivot(egui::Align2::CENTER_CENTER)
        .default_pos(ctx.content_rect().center())
        .open(&mut open)
        .show(ctx, |ui| {
            // Opens at full content height; shrinking it scrolls, and
            // the width-filling scroll area makes horizontal resize stick.
            egui::ScrollArea::vertical().auto_shrink([false, true]).show(ui, |ui| {
            ui.heading("Workbench");
            ui.label(egui::RichText::new("Example 3 of the .mobius tutorial — the terminal prefab (a port-less shell citizen), the egui_lens logger, and a nearly full ribbon.").italics());
            ui.add_space(8.0);
            ui.separator();
            ui.weak(format!("version {}", env!("CARGO_PKG_VERSION")));
            ui.add_space(8.0);
            ui.separator();
            ui.label(egui::RichText::new("Built with").strong());
            ui.add_space(2.0);
            egui::Grid::new("about_deps")
                .num_columns(3)
                .spacing([12.0, 2.0])
                .show(ui, |ui| {
                    for (name, version, what) in DEPENDENCIES {
                        ui.monospace(*name);
                        ui.weak(*version);
                        ui.weak(*what);
                        ui.end_row();
                    }
                });
            });
        });
    if !open {
        chrome.show_about.set(false);
    }
}

/// `Built with` rows for the About window — regenerate or edit freely.
const DEPENDENCIES: &[(&str, &str, &str)] = &[
    ("egui_citizen", "0.6.0", "citizen component model"),
    ("egui_mobius_reactive", "0.6.0", "Dynamic<T> reactive cells"),
    ("egui / eframe", "0.36", "immediate-mode UI"),
];

mod actions {
    //! Path B routing stubs — one handler per signal. Replace
    //! each body with real work: spawn it, send it over a
    //! channel, write results back into the interface cells.

    use crate::state::{Chrome, RibbonCmd, Log};

    pub fn handle_actions(cmd: RibbonCmd, _chrome: &Chrome, log: &Log) {
        let logger = egui_lens::ReactiveEventLogger::with_colors(&log.state, &log.colors);
        match cmd {
            RibbonCmd::New => logger.log_info("[actions] New"),
            RibbonCmd::Open => logger.log_info("[actions] Open"),
            RibbonCmd::Save => logger.log_info("[actions] Save"),
            RibbonCmd::Build => logger.log_info("[actions] Build"),
            RibbonCmd::Emit => logger.log_info("[actions] Emit"),
        }
    }
}

mod startup {
    //! Identity & environment — the welcome/dependency banner and
    //! host system details (the CopperForge convention), shared by
    //! the logger banner and the terminal's `ver` / `info`.

    pub const WELCOME: &str = concat!(
        "**** Welcome to Workbench, version ", env!("CARGO_PKG_VERSION"), "\n\n",
        "    DEPENDENCIES\n",
        "    egui_citizen         : 0.6.0\n",
        "    egui_mobius_reactive : 0.6.0\n",
        "    egui_lens            : 0.6.0\n",
        "    egui / eframe        : 0.36\n",
        "    egui_dock            : 0.21\n",
    );

    /// Linux: /etc/os-release + kernel version; elsewhere the OS constant.
    pub fn system_details() -> String {
        let name = std::fs::read_to_string("/etc/os-release")
            .ok()
            .and_then(|s| {
                s.lines().find_map(|l| {
                    l.strip_prefix("PRETTY_NAME=").map(|v| v.trim_matches('"').to_owned())
                })
            })
            .unwrap_or_else(|| std::env::consts::OS.to_owned());
        let kernel = std::fs::read_to_string("/proc/sys/kernel/osrelease")
            .map(|s| s.trim().to_owned())
            .unwrap_or_else(|_| "unknown".to_owned());
        format!("SYSTEM DETAILS\n\n    SYSTEM\n    System Name   : {name}\n    System Kernel : {kernel}")
    }

    use egui_lens::ReactiveEventLogger;

    pub fn banner(log: &crate::state::Log) {
        let logger = ReactiveEventLogger::with_colors(&log.state, &log.colors);
        logger.log_info("Startup: init");
        logger.log_info(WELCOME);
        logger.log_info(&system_details());
    }

    /// The System Info button: details first, banner last, so the
    /// banner reads on top in the circular buffer (CopperForge order).
    pub fn system_info(log: &crate::state::Log) {
        let logger = ReactiveEventLogger::with_colors(&log.state, &log.colors);
        logger.log_info(&system_details());
        logger.log_info(WELCOME);
    }
}

/// Wall clock (UTC, std-only) for the ribbon's clock slot.
fn wall_clock() -> String {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    format!("{:02}:{:02}:{:02} UTC", (secs / 3600) % 24, (secs / 60) % 60, secs % 60)
}

fn main() -> Result<(), eframe::Error> {
    eframe::run_native(
        "Workbench",
        eframe::NativeOptions {
            renderer: eframe::Renderer::Glow,
            viewport: egui::ViewportBuilder::default().with_inner_size([900.0, 420.0]),
            ..Default::default()
        },
        Box::new(|cc| {
            let app = App::new();
            app.chrome.theme.get().apply(&cc.egui_ctx);
            Ok(Box::new(app))
        }),
    )
}
